#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("NOOP\n");
        return 0;
    }

    int size = 0;
    long *heap = NULL;

    for (int i = 1; i < argc; i++) {
        char *endptr;
        long value = strtol(argv[i], &endptr, 10);
        if (endptr == argv[i]) {
            printf("ERR\n");
            continue;
        }

        if (size == 0) {
            heap = malloc(sizeof(long));
        } else {
            heap = realloc(heap, (size + 1) * sizeof(long));
        }
        heap[size] = value;
        size++;
        printf("INS %ld\n", value);
    }

    if (size > 0) {
        printf("MIN %ld\n", heap[0]);
        for (int i = 1; i < size; i++) {
            if (heap[i] < heap[0]) {
                long temp = heap[0];
                heap[0] = heap[i];
                heap[i] = temp;
            }
        }
    }

    free(heap);
    return 0;
}
